// Lee el perfil del usuario (config/user_profile.json) y el catálogo
// (config/modules.json), ambos montados en /files/config, y resuelve la
// configuración concreta que consumen los nodos siguientes.
const fs = require('fs');
const DIR = '/files/config';

let user = { selections: {}, ubicacion_laboral: '' };
let modules = {};
try { user = JSON.parse(fs.readFileSync(DIR + '/user_profile.json', 'utf8')); } catch (e) {}
try { modules = JSON.parse(fs.readFileSync(DIR + '/modules.json', 'utf8')); } catch (e) {}

const pick = (dim) => Array.isArray(user.selections && user.selections[dim]) ? user.selections[dim] : [];
const find = (list, id) => (list || []).find((o) => o && o.id === id);

const idiomaId = pick('idioma')[0] || 'espanol';
const idioma = (find(modules.idioma, idiomaId) && find(modules.idioma, idiomaId).valores.codigo) || 'es';

const LOCALE = {
  es: ['es', 'ES', 'ES:es'],
  ca: ['ca', 'ES', 'ES:ca'],
  en: ['en-US', 'US', 'US:en'],
  fr: ['fr', 'FR', 'FR:fr'],
  de: ['de', 'DE', 'DE:de'],
};
const loc = LOCALE[idioma] || LOCALE.es;
const hl = loc[0], gl = loc[1], ceid = loc[2];

const cats = [...new Set(
  pick('intereses_rss').flatMap((id) => {
    const m = find(modules.intereses_rss, id);
    return (m && m.valores && m.valores.categorias_feed) || [];
  })
)];

const query = cats.length ? '(' + cats.join(' OR ') + ')' : '(economía OR tecnología OR ciencia OR IA)';
const feed_url = 'https://news.google.com/rss/search?q=' + encodeURIComponent(query)
  + '&hl=' + hl + '&gl=' + gl + '&ceid=' + encodeURIComponent(ceid);

const estiloId = pick('estilo_marca_personal')[0];
const em = find(modules.estilo_marca_personal, estiloId);
const tono = (em && em.valores && em.valores.tono) || 'Claro, objetivo y sin adornos.';

return [{ json: { profile: {
  idioma,
  feed_url,
  tono,
  max_palabras: 80,
  categorias: cats,
  ubicacion: user.ubicacion_laboral || '',
} } }];

const title = ($json.title || '').trim();
const link = $json.link || $json.guid || '';
const norm = title.toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, '').trim();

return { json: {
  title,
  link,
  item_key: 'news:' + norm,
  source: 'news',
  text: (title + ' ' + ($json.contentSnippet || $json.content || '')).slice(0, 2000),
  isoDate: $json.isoDate || $json.pubDate || null,
} };

// Deduplicación persistente entre ejecuciones usando los datos estáticos
// del workflow (se guardan en la BD interna de n8n). Sin tabla externa.
const store = $getWorkflowStaticData('global');
const seen = store.newsSeen || {};
const now = Date.now();
const TTL = 30 * 24 * 60 * 60 * 1000; // 30 días

for (const k of Object.keys(seen)) {
  if (now - seen[k] > TTL) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const key = item.json.item_key;
  if (!key || key === 'news:' || seen[key]) continue;
  seen[key] = now;
  out.push({ json: item.json, pairedItem: item.pairedItem });
}
store.newsSeen = seen;
return out;

