const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let data;
try {
  const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content
    && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0]
    && $json.candidates[0].content.parts[0].text) || '{}';
  data = JSON.parse(raw);
} catch (e) {
  throw new Error('Respuesta de Gemini no es JSON válido: ' + e.message);
}
if (!data.titulo || !data.resumen) {
  throw new Error('JSON de Gemini incompleto (falta titulo o resumen)');
}

let enlace = '';
try { enlace = $('Normalizar noticia').item.json.link || ''; } catch (e) { enlace = ''; }

return { json: {
  titulo: esc(data.titulo),
  resumen: esc(data.resumen),
  relevancia: data.relevancia || '',
  enlace,
} };

